  c = mix(c, vec3(1.0, 0.98, 0.92), (1.0 - smoothstep(0.0, 0.006, edge)) * 0.75);
  // The foot sinks into haze.
  c = spray(c, HAZE, smoothstep(0.04, 0.22, edge) * 0.5 * far);
